<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Http};use Illuminate\Support\Str;use App\Models\User;
class MarketingAttributionJourneyTest extends TestCase{use RefreshDatabase;
 private function link():string{config(['marketing.attribution_enabled'=>true,'app.url'=>'http://localhost']);Http::preventStrayRequests();$u=User::factory()->create();$id=(string)Str::uuid();DB::table('marketing_tracking_links')->insert(['id'=>$id,'campaign_id'=>(string)Str::uuid(),'post_id'=>(string)Str::uuid(),'destination_id'=>(string)Str::uuid(),'merchant_key'=>app(\App\Services\Marketing\MarketingPosts::class)->merchant(),'user_id'=>$u->id,'post_version'=>1,'destination_url'=>'http://localhost/?keep=1#details']);return $id;}
 private function token(string $id):string{$r=$this->get('/m/r/'.$id.'?url=https://evil.example')->assertRedirect();$url=$r->headers->get('Location');$this->assertSame('localhost',parse_url($url,PHP_URL_HOST));$this->assertSame('details',parse_url($url,PHP_URL_FRAGMENT));parse_str(parse_url($url,PHP_URL_QUERY),$q);$this->assertSame('1',$q['keep']);return $q['jw_ref'];}
 public function test_guest_consent_redirect_and_duplicate_delivery_preserve_source(){ $id=$this->link();$token=$this->token($id);$this->assertDatabaseCount('marketing_analytics_events',1);$this->postJson('/marketing/tracking/arrival',['token'=>$token])->assertJsonPath('tracked',false);$this->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>$token])->assertJsonPath('accepted',true);$this->postJson('/marketing/tracking/arrival',['token'=>$token])->assertJsonPath('tracked',true);$this->assertSame(1,DB::table('marketing_analytics_events')->where('kind','arrival')->count());$this->postJson('/marketing/tracking/consent',['accepted'=>false])->assertJsonPath('accepted',false);$this->postJson('/marketing/tracking/page',['navigation_id'=>(string)Str::uuid()])->assertJsonPath('tracked',false);Http::assertNothingSent();}
 public function test_invalid_or_expired_source_does_not_create_a_visit(){ $id=$this->link();$token=$this->token($id);$this->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>'bad-token'])->assertOk();$this->assertSame(0,DB::table('marketing_analytics_events')->where('kind','arrival')->count());$this->travel(8)->days();$this->postJson('/marketing/tracking/arrival',['token'=>$token])->assertJsonPath('tracked',false);$this->assertSame(0,DB::table('marketing_analytics_events')->where('kind','arrival')->count());Http::assertNothingSent();}
 public function test_active_session_expires_after_inactivity_instead_of_becoming_a_permanent_visitor_id(){ $id=$this->link();$token=$this->token($id);$this->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>$token]);$first=session('marketing.sid');$this->assertNotEmpty($first);$this->travel(31)->minutes();$token=$this->token($id);$this->postJson('/marketing/tracking/arrival',['token'=>$token])->assertOk();$this->assertNotSame($first,session('marketing.sid'));Http::assertNothingSent();}
 public function test_browsing_does_not_extend_the_original_seven_day_click_window(){ $id=$this->link();$token=$this->token($id);$this->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>$token]);$clicked=session('marketing.last.at');$this->travel(4)->days();$this->postJson('/marketing/tracking/page',['navigation_id'=>(string)Str::uuid()])->assertJsonPath('tracked',true);$this->assertSame($clicked,session('marketing.last.at'));$this->travel(4)->days();$this->postJson('/marketing/tracking/page',['navigation_id'=>(string)Str::uuid()])->assertJsonPath('tracked',false);Http::assertNothingSent();}
 public function test_social_link_preview_is_not_a_qualified_visit(){ $id=$this->link();$token=$this->token($id);$this->withHeaders(['User-Agent'=>'facebookexternalhit/1.1'])->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>$token]);$this->withHeaders(['User-Agent'=>'facebookexternalhit/1.1'])->postJson('/marketing/tracking/arrival',['token'=>$token])->assertJsonPath('tracked',false);$this->assertSame(0,DB::table('marketing_analytics_events')->where('kind','arrival')->count());Http::assertNothingSent();}
}
